function integrityScore(depts,range){const groups=depts.map(d=>(KPI_CATALOG[d]||[]).map(k=>{const r=INTEGRITY_KPI_HISTORY.find(r=>r.definition_id===k.id&&r.period_start===range.from&&r.period_end===range.to);return r?{...k,ac:r.actual==null?null:Number(r.actual),pct:integrityKpiAchievement(r.actual,k.tgt,k.metadata),status:r.status,period:`${r.period_start} – ${r.period_end}`}:{...k,ac:null,pct:null};})),valid=groups.filter(rows=>rows.length&&rows.every(k=>k.ac!==null&&k.pct!==null&&['approved','locked'].includes(k.status)&&k.period===`${range.from} – ${range.to}`)&&Math.abs(rows.reduce((s,k)=>s+k.w,0)-1)<1e-6);if(!valid.length)return null;return Math.round(valid.reduce((sum,rows)=>sum+rows.reduce((n,k)=>n+Math.min(100,k.pct)*k.w,0),0)/valid.length);}
